/**
 * Simplified India state boundaries (GADM-derived, Douglas-Peucker simplified),
 * pre-projected into a 100 x 122.80 equirectangular viewBox.
 */
export const MAP_WIDTH = 100;
export const MAP_HEIGHT = 122.80;

export const INDIA_BOUNDS = { minLon: 68.0, maxLon: 97.5, minLat: 6.5, maxLat: 37.2 };

export function projectToMap(lat: number, lon: number) {
  return {
    x: ((lon - INDIA_BOUNDS.minLon) / (INDIA_BOUNDS.maxLon - INDIA_BOUNDS.minLon)) * MAP_WIDTH,
    y: ((INDIA_BOUNDS.maxLat - lat) / (INDIA_BOUNDS.maxLat - INDIA_BOUNDS.minLat)) * MAP_HEIGHT,
  };
}

export interface StateShape {
  name: string;
  cx: number;
  cy: number;
  d: string;
}

